<template>
  <div class="room-detail">
    <header class="detail-head">
      <div class="title"><el-button :icon="ArrowLeft" circle text @click="router.push('/live-ops/liveMetrics')"/><div><h2>{{ room.roomName || '直播间' }}</h2><p>{{ anchors.length }} 位可上报主播</p></div></div>
      <div class="head-actions">
        <el-button v-hasPermi="['live:metrics:manage']" type="primary" :icon="Plus" @click="createSegment">新增补录</el-button>
        <el-button :icon="User" v-hasPermi="['live:metrics:manage']" @click="anchorDialog=true">主播管理</el-button>
      </div>
    </header>
    <div class="filters">
      <el-radio-group v-model="range" @change="applyRange"><el-radio-button value="today">今天</el-radio-button><el-radio-button value="7">近 7 天</el-radio-button><el-radio-button value="30">近 30 天</el-radio-button><el-radio-button value="custom">自定义</el-radio-button></el-radio-group>
      <el-date-picker v-if="range==='custom'" v-model="dates" type="daterange" value-format="YYYY-MM-DD" format="YYYY年M月D日" range-separator="至" :clearable="false" @change="loadRoom"/>
      <el-button :icon="Refresh" circle title="刷新" :loading="loading" @click="loadRoom"/>
    </div>
    <section v-loading="loading" class="table-panel">
      <div v-if="tableRows.length" class="handover-table-wrap">
        <table class="handover-table">
          <thead><tr><th class="session-column">开播时间</th><th>主播</th><th class="period-column">上播区间</th><th>上播时长</th><th>数据来源</th><th v-for="metric in metrics" :key="metric.key">{{ metric.label }}</th><th class="action-column">操作</th></tr></thead>
          <tbody>
            <tr v-for="row in tableRows" :key="row.key" :class="row.tone">
              <td v-if="row.sessionRowIndex===0" :rowspan="row.sessionRowspan" class="session-cell">
                <strong>{{ datetime(row.session.liveStartTime) }}</strong><small>最近上报 {{ datetime(row.session.lastSnapshotAt) }}</small>
                <el-tag v-if="Number(row.session.exceptionCount)" size="small" type="warning" effect="plain">{{ row.session.exceptionCount }} 个待核对</el-tag>
              </td>
              <template v-if="row.segment">
                <td><strong>{{ row.segment.anchorName }}</strong></td>
                <td class="period-cell">{{ datetime(row.segment.startTime) }}<span>至</span>{{ datetime(row.segment.endTime) }}</td>
                <td class="duration-cell">{{ duration(row.segment.startTime,row.segment.endTime) }}</td>
                <td><el-tag size="small" :type="row.segment.source==='MANUAL'?'warning':row.segment.source==='AUTO'?'info':'success'">{{ sourceLabel(row.segment.source) }}</el-tag></td>
                <td v-for="metric in metrics" :key="metric.key" class="metric-cell" :class="{money:metric.type==='money'}">{{ metricValue(row.segment,metric) }}</td>
                <td><el-button v-hasPermi="['live:metrics:manage']" text :icon="Edit" @click="editSegment(row.session,row.segment)">调整</el-button></td>
              </template>
              <template v-else><td colspan="15" class="empty-cell">暂无主播记录，可使用页面上方“新增补录”添加</td></template>
            </tr>
          </tbody>
        </table>
      </div>
      <el-empty v-if="!loading&&!tableRows.length" description="这个日期范围暂无直播场次"/>
    </section>
    <el-dialog v-model="editOpen" :title="editing?'调整主播记录':'补录主播记录'" width="min(760px,94vw)" class="segment-dialog" destroy-on-close>
      <el-alert title="开始或结束时间要接上已有记录。连续漏报两场时，请按时间先后分两次补录。" type="warning" :closable="false" show-icon/>
      <el-form ref="editRef" :model="edit" :rules="rules" label-position="top" class="edit-form">
        <el-form-item v-if="!editing" label="直播场次" prop="sessionId"><el-select v-model="edit.sessionId" placeholder="请选择需要补录的直播场次" style="width:100%" @change="sessionChanged"><el-option v-for="item in sortedSessions" :key="item.sessionId" :label="`${datetime(item.liveStartTime)} 开播${item.reportedRoomName?' · '+item.reportedRoomName:''}`" :value="Number(item.sessionId)"/></el-select></el-form-item>
        <el-form-item v-if="!editing" label="漏报位置" prop="position"><el-select v-model="edit.position" placeholder="请选择是哪一场忘记上报" style="width:100%" @change="positionChanged"><el-option v-for="item in positionOptions" :key="item.value" :label="item.label" :value="item.value"/></el-select><div v-if="selectedPosition" class="position-help">{{ selectedPosition.help }}</div></el-form-item>
        <el-form-item label="主播" prop="anchorUserId"><el-select v-model="edit.anchorUserId" style="width:100%"><el-option v-for="item in anchors" :key="item.userId" :label="item.userName" :value="Number(item.userId)"/></el-select></el-form-item>
        <div class="boundary"><el-form-item label="开始时间" prop="startTime"><el-input v-if="!editing" :model-value="edit.startTime?datetime(edit.startTime):''" disabled placeholder="选择漏报位置后自动确定"/><el-date-picker v-else v-model="edit.startTime" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" format="YYYY-MM-DD HH:mm" placeholder="选择实际上播时间"/></el-form-item><el-form-item label="结束时间" prop="endTime"><el-date-picker v-model="edit.endTime" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" format="YYYY-MM-DD HH:mm" placeholder="选择实际下播时间"/></el-form-item></div>
        <div class="section-title"><strong>该时段直播数据</strong><span>请按直播大屏显示填写</span></div>
        <div class="metric-form"><el-form-item v-for="metric in metrics" :key="metric.key"><template #label><span>{{ metric.label }}</span><small v-if="metricLimit(metric)!=null">最多 {{ metricLimitText(metric) }}</small></template><el-input-number v-model="edit[metric.key]" :min="0" :max="metric.type==='rate'?100:999999999999" :precision="metric.type==='money'?2:metric.type==='rate'?2:0" :controls="false"/><span v-if="metric.type==='rate'" class="input-suffix">%</span></el-form-item></div>
        <div v-if="!editing&&selectedPosition" class="recalc-preview"><strong>保存后</strong><span>新增 {{ selectedAnchorName||'所选主播' }} · {{ datetime(edit.startTime) }} 至 {{ edit.endTime?datetime(edit.endTime):'待选择' }}<template v-if="edit.startTime&&edit.endTime"> · {{ duration(edit.startTime,edit.endTime) }}</template></span><span v-if="affectedSegment">已带入 {{ affectedSegment.anchorName }} 的原记录数据，请改成漏报主播在该时段的实际数据；保存后系统会重新计算 {{ affectedSegment.anchorName }}。</span><span v-else>不会改动已有主播记录</span><span v-if="metricsUnchanged" class="unchanged-tip">至少修改一项直播数据后才能确认补录</span></div>
        <el-form-item :label="editing?'调整或作废原因（必填）':'补录说明（选填）'" prop="reason"><el-input v-model="edit.reason" type="textarea" :rows="3" maxlength="200" :placeholder="editing?'请说明调整或作废原因':'可填写漏报原因或其他说明'" show-word-limit/></el-form-item>
      </el-form>
      <template #footer><div class="edit-footer"><el-button v-if="editing" type="danger" plain :icon="Delete" :loading="saving" @click="voidSegment">作废上报</el-button><span/><el-button @click="editOpen=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!editing&&metricsUnchanged" @click="saveSegment">{{ editing?'保存调整':'确认补录' }}</el-button></div></template>
    </el-dialog>
    <el-dialog v-model="anchorDialog" title="主播管理" width="min(560px,94vw)"><div class="anchor-add"><el-select v-model="newAnchor" filterable placeholder="选择系统用户"><el-option v-for="item in availableStaff" :key="item.userId" :label="item.userName" :value="Number(item.userId)"/></el-select><el-button type="primary" :disabled="!newAnchor" @click="addAnchor">添加主播</el-button></div><div class="anchor-list"><div v-for="item in anchors" :key="item.userId"><strong>{{ item.userName }}</strong><el-button text type="danger" :icon="Delete" @click="removeAnchor(item)">移除</el-button></div></div><el-empty v-if="!anchors.length" description="当前直播间还没有主播" :image-size="70"/></el-dialog>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowLeft, Delete, Edit, Plus, Refresh, User } from '@element-plus/icons-vue'
import { addHandoverAnchor, createHandoverSegment, voidHandoverSegment, getHandoverRoom, removeHandoverAnchor, updateHandoverSegment } from '@/api/liveMetrics'
const route=useRoute(),router=useRouter(),roomId=Number(route.params.roomId),pad=v=>String(v).padStart(2,'0'),date=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`
const now=new Date(),room=reactive({}),anchors=ref([]),staff=ref([]),sessions=ref([]),dates=ref([date(new Date(now.getTime()-6*86400000)),date(now)]),range=ref('7'),loading=ref(false),anchorDialog=ref(false),newAnchor=ref(null),activeSession=ref(null),editOpen=ref(false),editing=ref(false),saving=ref(false),editRef=ref()
const emptyMetrics={gmvDelta:0,watchDelta:0,newFanDelta:0,dealDelta:0,adCostDelta:0,exposureWatchRate:0,watchFollowRate:0,watchInteractionRate:0,watchDealRate:0,presaleOrderDelta:0}
const edit=reactive({sessionId:null,position:null,segmentId:null,anchorUserId:null,dataMode:'MANUAL',startTime:null,endTime:null,version:0,reason:'',...emptyMetrics}),rules={sessionId:[{required:true,message:'请选择直播场次'}],position:[{validator:(_rule,value,callback)=>!editing.value&&!value?callback(new Error('请选择漏报位置')):callback()}],anchorUserId:[{required:true,message:'请选择主播'}],startTime:[{required:true,message:'请选择开始时间'}],endTime:[{required:true,message:'请选择结束时间'}],reason:[{validator:(_rule,value,callback)=>editing.value&&!String(value||'').trim()?callback(new Error('请填写调整原因')):callback()}]}
const metrics=[{key:'gmvDelta',label:'成交金额',type:'money'},{key:'watchDelta',label:'观看人数'},{key:'newFanDelta',label:'新增粉丝'},{key:'dealDelta',label:'成交人数'},{key:'adCostDelta',label:'投流消耗',type:'money'},{key:'exposureWatchRate',label:'进房率',type:'rate'},{key:'watchFollowRate',label:'转粉率',type:'rate'},{key:'watchInteractionRate',label:'互动率',type:'rate'},{key:'watchDealRate',label:'成交率',type:'rate'},{key:'presaleOrderDelta',label:'预售订单'}]
const availableStaff=computed(()=>staff.value.filter(person=>!anchors.value.some(anchor=>Number(anchor.userId)===Number(person.userId))))
const sortedSessions=computed(()=>[...sessions.value].sort((a,b)=>time(b.liveStartTime)-time(a.liveStartTime)))
const activeSegments=computed(()=>[...(activeSession.value?.segments||[])].sort((a,b)=>time(a.startTime)-time(b.startTime)))
const positionOptions=computed(()=>{const list=activeSegments.value,options=[{value:'FIRST',label:'第一场忘记上报',start:activeSession.value?.liveStartTime,target:list[0]||null,help:'开始时间已自动使用本场开播时间，只需选择实际结束时间。'}];for(let i=1;i<list.length;i++){const item=list[i];options.push({value:`BEFORE:${item.segmentId}`,label:`在 ${item.anchorName} 之前补录（${datetime(item.startTime)} 开始）`,start:item.startTime,target:item,help:`开始时间已接上 ${item.anchorName} 的记录，保存后会自动重新计算其后续数据。`})}if(list.length){const last=list[list.length-1];options.push({value:'LAST',label:`最后一场忘记上报（接在 ${last.anchorName} 之后）`,start:last.endTime,target:null,help:`开始时间已接上 ${last.anchorName} 的结束时间，只需选择实际下播时间。`})}return options})
const selectedPosition=computed(()=>positionOptions.value.find(item=>item.value===edit.position)||null)
const affectedSegment=computed(()=>selectedPosition.value?.target||null)
const metricsUnchanged=computed(()=>!!affectedSegment.value&&metrics.every(metric=>Number(edit[metric.key]??0)===Number(affectedSegment.value[metric.key]??0)))
const selectedAnchorName=computed(()=>anchors.value.find(item=>Number(item.userId)===Number(edit.anchorUserId))?.userName||'')
const nextSegment=computed(()=>{const index=activeSegments.value.findIndex(item=>Number(item.segmentId)===Number(edit.segmentId));return index>=0?activeSegments.value[index+1]||null:null})
const tableRows=computed(()=>{const tones=new Map(),toneNames=['session-tone-orange','session-tone-blue','session-tone-green','session-tone-gray'];let toneIndex=0;return sortedSessions.value.flatMap(session=>{const toneKey=String(session.liveStartTime||'');if(!tones.has(toneKey))tones.set(toneKey,toneNames[toneIndex++%toneNames.length]);const segments=[...(session.segments||[])].sort((a,b)=>time(a.startTime)-time(b.startTime)),items=segments.length?segments:[null];return items.map((segment,index)=>({key:segment?.segmentId||`empty-${session.sessionId}`,session,segment,sessionRowIndex:index,sessionRowspan:items.length,tone:tones.get(toneKey)}))})})
const datetime=value=>value?String(value).replace('T',' ').slice(0,16):'-',number=value=>value==null?'-':Number(value).toLocaleString('zh-CN'),money=value=>value==null?'-':Number(value).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})
const time=value=>value?new Date(String(value).replace(' ','T')).getTime():0
const duration=(start,end)=>{const minutes=Math.max(0,Math.round((time(end)-time(start))/60000));if(!minutes&&(!start||!end))return'-';const hours=Math.floor(minutes/60),rest=minutes%60;return hours?`${hours}小时${rest?rest+'分钟':''}`:`${rest}分钟`}
const metricValue=(item,metric)=>metric.type==='money'?`¥${money(item?.[metric.key])}`:metric.type==='rate'?(item?.[metric.key]==null?'-':`${Number(item[metric.key]).toFixed(2)}%`):number(item?.[metric.key])
const sourceLabel=source=>({PLUGIN:'插件上报',AUTO:'系统计算',MANUAL:'人工补录',ADJUSTED:'补录重算'}[source]||'人工记录')
function applyRange(value){if(value==='custom')return;const days=value==='today'?0:Number(value)-1;dates.value=[date(new Date(now.getTime()-days*86400000)),date(now)];loadRoom()}
async function loadRoom(){loading.value=true;try{const data=(await getHandoverRoom(roomId,{beginDate:dates.value[0],endDate:dates.value[1]})).data||{};Object.assign(room,data);anchors.value=data.anchors||[];staff.value=data.staff||[];sessions.value=data.sessions||[]}finally{loading.value=false}}
function resetEdit(){Object.assign(edit,{sessionId:null,position:null,segmentId:null,anchorUserId:null,dataMode:'MANUAL',startTime:null,endTime:null,version:0,reason:'',...emptyMetrics})}
function createSegment(){editing.value=false;resetEdit();const latest=sortedSessions.value[0];if(latest){edit.sessionId=Number(latest.sessionId);sessionChanged(edit.sessionId)}editOpen.value=true}
function sessionChanged(sessionId){activeSession.value=sessions.value.find(item=>Number(item.sessionId)===Number(sessionId))||null;edit.position=null;edit.startTime=null;edit.endTime=null;fillMetrics(null)}
function fillMetrics(source){for(const metric of metrics)edit[metric.key]=Number(source?.[metric.key]??0)}
function positionChanged(value){const option=positionOptions.value.find(item=>item.value===value);edit.startTime=option?.start?String(option.start).replace('T',' ').slice(0,19):null;edit.endTime=null;fillMetrics(option?.target)}
function editSegment(session,item){activeSession.value=session;editing.value=true;resetEdit();Object.assign(edit,{segmentId:item.segmentId,anchorUserId:Number(item.anchorUserId),dataMode:'MANUAL',startTime:String(item.startTime).replace('T',' ').slice(0,19),endTime:String(item.endTime).replace('T',' ').slice(0,19),version:Number(item.version),reason:'',...Object.fromEntries(metrics.map(metric=>[metric.key,Number(item[metric.key]||0)]))});editOpen.value=true}
async function saveSegment(){if(!editing.value&&metricsUnchanged.value)return ElMessage.warning('请先把带入的数据改成漏报主播的实际数据');const valid=await editRef.value?.validate().catch(()=>false);if(!valid)return;const start=time(edit.startTime),end=time(edit.endTime),liveStart=time(activeSession.value?.liveStartTime);if(end<=start)return ElMessage.warning('结束时间必须晚于开始时间');if(start<liveStart)return ElMessage.warning('开始时间不能早于本场开播时间');if(end>Date.now()+60000)return ElMessage.warning('结束时间不能晚于当前时间');saving.value=true;try{if(editing.value)await updateHandoverSegment(edit.segmentId,{...edit});else await createHandoverSegment(activeSession.value.sessionId,{...edit});ElMessage.success(editing.value?'记录已调整':'补录完成，相邻记录已重新计算');editOpen.value=false;await loadRoom()}finally{saving.value=false}}
async function voidSegment(){if(!edit.reason.trim())return ElMessage.warning('请先填写作废原因');const next=nextSegment.value,message=next?`作废后，“${next.anchorName}”将从 ${datetime(edit.startTime)} 开始重新计算，本条上报会保留在操作记录中。`:'这是本场最后一条上报。作废后，下一次插件上报会从本条开始时间重新计算，本条仍保留在操作记录中。';await ElMessageBox.confirm(message,'确认作废上报',{type:'warning',confirmButtonText:'确认作废并重算',cancelButtonText:'取消'});saving.value=true;try{const result=(await voidHandoverSegment(edit.segmentId,{version:edit.version,reason:edit.reason})).data||{};ElMessage.success(result.recalculatedAnchorName?`已作废，并重新计算 ${result.recalculatedAnchorName}`:'已作废，下一次上报将自动接续');editOpen.value=false;await loadRoom()}finally{saving.value=false}}
function metricLimit(metric){if(!affectedSegment.value||metric.type==='rate')return null;return Number(affectedSegment.value[metric.key]??0)}
function metricLimitText(metric){const value=metricLimit(metric);return metric.type==='money'?`¥${money(value)}`:number(value)}
async function addAnchor(){await addHandoverAnchor(roomId,newAnchor.value);newAnchor.value=null;ElMessage.success('主播已添加');await loadRoom()}
async function removeAnchor(item){await ElMessageBox.confirm(`确定移除“${item.userName}”吗？历史记录不会删除。`,'移除主播',{type:'warning'});await removeHandoverAnchor(roomId,item.userId);ElMessage.success('主播已移除');await loadRoom()}
onMounted(loadRoom)
</script>
<style scoped>
