.table-panel{min-height:360px}.handover-table-wrap{overflow:auto;border:1px solid #dfe4ea;border-radius:6px;background:#fff}.handover-table{width:100%;min-width:1840px;border-collapse:separate;border-spacing:0;color:#354052;font-size:13px}.handover-table th{position:sticky;top:0;z-index:3;height:42px;padding:0 10px;border-right:1px solid #e5e9ee;border-bottom:1px solid #d9dfe6;background:#f5f6f8;color:#606a78;font-weight:600;text-align:center;white-space:nowrap}.handover-table td{height:54px;padding:8px 10px;border-right:1px solid rgba(214,220,227,.9);border-bottom:1px solid rgba(214,220,227,.9);text-align:center;white-space:nowrap;transition:background-color .15s}.handover-table tr:last-child td{border-bottom:0}.handover-table th:last-child,.handover-table td:last-child{border-right:0}.handover-table th:first-child{left:0;z-index:5}.handover-table th:last-child{right:0;z-index:5}.handover-table td:last-child{position:sticky;right:0;z-index:2;box-shadow:-1px 0 #dde2e8}.session-column{width:165px}.period-column{width:230px}.action-column{width:76px}.session-cell{position:sticky;left:0;z-index:2;width:165px;min-width:165px;box-shadow:1px 0 #dde2e8;text-align:left!important;vertical-align:middle}.session-cell strong,.session-cell small{display:block}.session-cell strong{color:#2f3947;font-size:14px}.session-cell small{margin-top:4px;color:#7e8996;font-size:11px}.session-cell .el-tag{margin-top:7px}.session-cell .el-button{display:flex;margin-top:8px}.period-cell{color:#596575}.period-cell span{margin:0 6px;color:#9aa3ae}.duration-cell{min-width:92px;color:#596575}.metric-cell{min-width:94px;font-variant-numeric:tabular-nums}.metric-cell.money{color:#dc5b19;font-weight:600}.empty-cell{position:static!important;height:70px!important;color:#87919d;text-align:left!important}.session-tone-orange td{background:#fff8f3}.session-tone-blue td{background:#f5f9ff}.session-tone-green td{background:#f4faf6}.session-tone-gray td{background:#f8f8fa}.handover-table tbody tr:hover td{b